-- ============================================================
-- LogiSense — LOGISENSE schema definition
-- Target: Exasol SaaS
-- All PKs are VARCHAR(36) UUIDs generated by the Python layer.
-- Run via: python scripts/setup_db.py
-- ============================================================

CREATE SCHEMA IF NOT EXISTS LOGISENSE;

-- ------------------------------------------------------------
-- MACHINES
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.MACHINES (
    MACHINE_ID      VARCHAR(36)     NOT NULL,
    MACHINE_NAME    VARCHAR(100)    NOT NULL,
    MACHINE_TYPE    VARCHAR(50)     NOT NULL,
    LOCATION        VARCHAR(100)    NOT NULL,
    INSTALL_DATE    DATE            NOT NULL,
    STATUS          VARCHAR(20)     NOT NULL,
    CONSTRAINT PK_MACHINES PRIMARY KEY (MACHINE_ID)
);

-- ------------------------------------------------------------
-- SENSORS
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.SENSORS (
    SENSOR_ID       VARCHAR(36)     NOT NULL,
    MACHINE_ID      VARCHAR(36)     NOT NULL,
    SENSOR_TYPE     VARCHAR(30)     NOT NULL,
    UNIT            VARCHAR(20)     NOT NULL,
    THRESHOLD_WARN  DECIMAL(10,3)   NOT NULL,
    THRESHOLD_CRIT  DECIMAL(10,3)   NOT NULL,
    CONSTRAINT PK_SENSORS PRIMARY KEY (SENSOR_ID),
    CONSTRAINT FK_SENSOR_MACHINE FOREIGN KEY (MACHINE_ID) REFERENCES LOGISENSE.MACHINES (MACHINE_ID)
);

-- ------------------------------------------------------------
-- SENSOR_READINGS
-- High-frequency time-series (the large fact table).
-- Planted pattern: READING_VALUE trends up 6-48 h before each downtime event.
-- NOTE: "VALUE" is a reserved keyword in Exasol; column is named READING_VALUE.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.SENSOR_READINGS (
    READING_ID      VARCHAR(36)     NOT NULL,
    SENSOR_ID       VARCHAR(36)     NOT NULL,
    TS              TIMESTAMP       NOT NULL,
    READING_VALUE   DECIMAL(12,4)   NOT NULL,
    CONSTRAINT PK_SENSOR_READINGS PRIMARY KEY (READING_ID),
    CONSTRAINT FK_READING_SENSOR FOREIGN KEY (SENSOR_ID) REFERENCES LOGISENSE.SENSORS (SENSOR_ID)
);

-- ------------------------------------------------------------
-- DOWNTIME_EVENTS
-- Planted pattern: fault sequence E12 then E31 then E07 repeats across machines.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.DOWNTIME_EVENTS (
    EVENT_ID            VARCHAR(36)     NOT NULL,
    MACHINE_ID          VARCHAR(36)     NOT NULL,
    START_TS            TIMESTAMP       NOT NULL,
    END_TS              TIMESTAMP,
    DURATION_H          DECIMAL(8,2),
    FAULT_CODE          VARCHAR(10)     NOT NULL,
    ROOT_CAUSE          VARCHAR(200),
    MAINTENANCE_COST    DECIMAL(12,2),
    CONSTRAINT PK_DOWNTIME_EVENTS PRIMARY KEY (EVENT_ID),
    CONSTRAINT FK_EVENT_MACHINE FOREIGN KEY (MACHINE_ID) REFERENCES LOGISENSE.MACHINES (MACHINE_ID)
);

-- ------------------------------------------------------------
-- WORK_ORDERS
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.WORK_ORDERS (
    WO_ID           VARCHAR(36)     NOT NULL,
    MACHINE_ID      VARCHAR(36)     NOT NULL,
    EVENT_ID        VARCHAR(36),
    WO_TYPE         VARCHAR(30)     NOT NULL,
    STATUS          VARCHAR(20)     NOT NULL,
    ASSIGNED_TO     VARCHAR(100),
    OPENED_AT       TIMESTAMP       NOT NULL,
    CLOSED_AT       TIMESTAMP,
    NOTES           VARCHAR(1000),
    CONSTRAINT PK_WORK_ORDERS PRIMARY KEY (WO_ID),
    CONSTRAINT FK_WO_MACHINE FOREIGN KEY (MACHINE_ID) REFERENCES LOGISENSE.MACHINES (MACHINE_ID)
);

-- ------------------------------------------------------------
-- PARTS_CATALOG
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.PARTS_CATALOG (
    PART_ID             VARCHAR(36)     NOT NULL,
    PART_NAME           VARCHAR(100)    NOT NULL,
    CATEGORY            VARCHAR(50)     NOT NULL,
    UNIT_COST           DECIMAL(12,2)   NOT NULL,
    LEAD_TIME_DAYS      INTEGER         NOT NULL,
    REORDER_POINT       INTEGER         NOT NULL,
    CONSTRAINT PK_PARTS_CATALOG PRIMARY KEY (PART_ID)
);

-- ------------------------------------------------------------
-- WAREHOUSES
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.WAREHOUSES (
    WAREHOUSE_ID    VARCHAR(36)     NOT NULL,
    WAREHOUSE_NAME  VARCHAR(100)    NOT NULL,
    LOCATION        VARCHAR(100)    NOT NULL,
    CAPACITY        INTEGER         NOT NULL,
    CONSTRAINT PK_WAREHOUSES PRIMARY KEY (WAREHOUSE_ID)
);

-- ------------------------------------------------------------
-- INVENTORY
-- Planted pattern: some warehouses massively overstocked,
-- others at or below reorder_point for the same part.
-- NOTE: DEFAULT must come before NOT NULL in Exasol.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.INVENTORY (
    INVENTORY_ID    VARCHAR(36)     NOT NULL,
    WAREHOUSE_ID    VARCHAR(36)     NOT NULL,
    PART_ID         VARCHAR(36)     NOT NULL,
    QTY_ON_HAND     INTEGER         DEFAULT 0 NOT NULL,
    LAST_UPDATED    TIMESTAMP       NOT NULL,
    CONSTRAINT PK_INVENTORY PRIMARY KEY (INVENTORY_ID),
    CONSTRAINT FK_INV_WAREHOUSE FOREIGN KEY (WAREHOUSE_ID) REFERENCES LOGISENSE.WAREHOUSES (WAREHOUSE_ID),
    CONSTRAINT FK_INV_PART     FOREIGN KEY (PART_ID)       REFERENCES LOGISENSE.PARTS_CATALOG (PART_ID)
);

-- ------------------------------------------------------------
-- STOCK_TRANSFERS
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.STOCK_TRANSFERS (
    TRANSFER_ID         VARCHAR(36)     NOT NULL,
    FROM_WAREHOUSE_ID   VARCHAR(36)     NOT NULL,
    TO_WAREHOUSE_ID     VARCHAR(36)     NOT NULL,
    PART_ID             VARCHAR(36)     NOT NULL,
    QTY                 INTEGER         NOT NULL,
    REQUESTED_AT        TIMESTAMP       NOT NULL,
    COMPLETED_AT        TIMESTAMP,
    STATUS              VARCHAR(20)     NOT NULL,
    CONSTRAINT PK_STOCK_TRANSFERS PRIMARY KEY (TRANSFER_ID),
    CONSTRAINT FK_TRANS_FROM FOREIGN KEY (FROM_WAREHOUSE_ID) REFERENCES LOGISENSE.WAREHOUSES (WAREHOUSE_ID),
    CONSTRAINT FK_TRANS_TO   FOREIGN KEY (TO_WAREHOUSE_ID)   REFERENCES LOGISENSE.WAREHOUSES (WAREHOUSE_ID),
    CONSTRAINT FK_TRANS_PART FOREIGN KEY (PART_ID)           REFERENCES LOGISENSE.PARTS_CATALOG (PART_ID)
);

-- ------------------------------------------------------------
-- QUALITY_CHECKS
-- CHECK_STAGE: EARLY (in-process), MID (sub-assembly), FINAL (end-of-line).
-- Planted pattern: EARLY defect_rate spikes 2-5 days before FINAL failures.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.QUALITY_CHECKS (
    CHECK_ID        VARCHAR(36)     NOT NULL,
    MACHINE_ID      VARCHAR(36)     NOT NULL,
    CHECK_STAGE     VARCHAR(20)     NOT NULL,
    TS              TIMESTAMP       NOT NULL,
    DEFECT_TYPE     VARCHAR(50)     NOT NULL,
    DEFECT_COUNT    INTEGER         DEFAULT 0 NOT NULL,
    SAMPLE_SIZE     INTEGER         NOT NULL,
    DEFECT_RATE     DECIMAL(8,5)    NOT NULL,
    CONSTRAINT PK_QUALITY_CHECKS PRIMARY KEY (CHECK_ID),
    CONSTRAINT FK_QC_MACHINE FOREIGN KEY (MACHINE_ID) REFERENCES LOGISENSE.MACHINES (MACHINE_ID)
);

-- ------------------------------------------------------------
-- SUPPLIERS
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.SUPPLIERS (
    SUPPLIER_ID     VARCHAR(36)     NOT NULL,
    SUPPLIER_NAME   VARCHAR(100)    NOT NULL,
    COUNTRY         VARCHAR(50)     NOT NULL,
    CONTACT_EMAIL   VARCHAR(150),
    PAYMENT_TERMS   VARCHAR(30),
    LEAD_TIME_DAYS  INTEGER,
    ON_TIME_RATE    DECIMAL(5,3),
    QUALITY_SCORE   DECIMAL(5,3),
    CONSTRAINT PK_SUPPLIERS PRIMARY KEY (SUPPLIER_ID)
);

-- ------------------------------------------------------------
-- SUPPLIER_DELIVERIES
-- Planted pattern: mixed currencies USD/EUR/INR/GBP and random delay patterns.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.SUPPLIER_DELIVERIES (
    DELIVERY_ID     VARCHAR(36)     NOT NULL,
    SUPPLIER_ID     VARCHAR(36)     NOT NULL,
    PART_ID         VARCHAR(36)     NOT NULL,
    ORDER_DATE      DATE            NOT NULL,
    EXPECTED_DATE   DATE            NOT NULL,
    ACTUAL_DATE     DATE,
    QTY_ORDERED     INTEGER         NOT NULL,
    QTY_RECEIVED    INTEGER,
    UNIT_COST       DECIMAL(12,4)   NOT NULL,
    CURRENCY        VARCHAR(5)      DEFAULT 'USD' NOT NULL,
    DELAY_DAYS      INTEGER,
    CONSTRAINT PK_SUPPLIER_DELIVERIES PRIMARY KEY (DELIVERY_ID),
    CONSTRAINT FK_DEL_SUPPLIER FOREIGN KEY (SUPPLIER_ID) REFERENCES LOGISENSE.SUPPLIERS     (SUPPLIER_ID),
    CONSTRAINT FK_DEL_PART     FOREIGN KEY (PART_ID)     REFERENCES LOGISENSE.PARTS_CATALOG (PART_ID)
);

-- ------------------------------------------------------------
-- SUPPLIER_FILES — staging table for raw uploaded files
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.SUPPLIER_FILES (
    FILE_ID         VARCHAR(36)     NOT NULL,
    SUPPLIER_ID     VARCHAR(36),
    FILENAME        VARCHAR(255)    NOT NULL,
    UPLOADED_AT     TIMESTAMP       NOT NULL,
    ROW_COUNT       INTEGER,
    STATUS          VARCHAR(20)     DEFAULT 'PENDING' NOT NULL,
    ERROR_MSG       VARCHAR(2000),
    CONSTRAINT PK_SUPPLIER_FILES PRIMARY KEY (FILE_ID),
    CONSTRAINT FK_FILE_SUPPLIER FOREIGN KEY (SUPPLIER_ID) REFERENCES LOGISENSE.SUPPLIERS (SUPPLIER_ID)
);

-- ------------------------------------------------------------
-- USERS — application authentication (JWT)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS LOGISENSE.USERS (
    USER_ID         VARCHAR(36)     NOT NULL,
    EMAIL           VARCHAR(150)    NOT NULL,
    HASHED_PASSWORD VARCHAR(255)    NOT NULL,
    FULL_NAME       VARCHAR(100)    NOT NULL,
    ROLE            VARCHAR(20)     NOT NULL,
    CREATED_AT      TIMESTAMP       NOT NULL,
    IS_ACTIVE       BOOLEAN         DEFAULT TRUE NOT NULL,
    CONSTRAINT PK_USERS PRIMARY KEY (USER_ID)
);
